# Minimal XRechnung 3.0 CII writer. Writes exactly the numbers it is given (no arithmetic),
# so that the conversion strategy under test owns every amount.
from xml.sax.saxutils import escape as E
def amt(x): return format(x,'f')
def write(inv):
    L=[]
    for i,l in enumerate(inv['lines'],1):
        allow="".join(f"""<ram:SpecifiedTradeAllowanceCharge><ram:ChargeIndicator><udt:Indicator>false</udt:Indicator></ram:ChargeIndicator><ram:ActualAmount>{amt(a)}</ram:ActualAmount><ram:Reason>Rabatt</ram:Reason></ram:SpecifiedTradeAllowanceCharge>""" for a in l.get('allow',[]))
        bq=f' unitCode="{l.get("unit","H87")}"'
        basis=f"<ram:BasisQuantity{bq}>{amt(l['base_qty'])}</ram:BasisQuantity>" if l.get('base_qty') else ""
        L.append(f"""<ram:IncludedSupplyChainTradeLineItem><ram:AssociatedDocumentLineDocument><ram:LineID>{i}</ram:LineID></ram:AssociatedDocumentLineDocument><ram:SpecifiedTradeProduct><ram:Name>{E(l['name'])}</ram:Name></ram:SpecifiedTradeProduct><ram:SpecifiedLineTradeAgreement><ram:NetPriceProductTradePrice><ram:ChargeAmount>{amt(l['net_price'])}</ram:ChargeAmount>{basis}</ram:NetPriceProductTradePrice></ram:SpecifiedLineTradeAgreement><ram:SpecifiedLineTradeDelivery><ram:BilledQuantity{bq}>{amt(l['qty'])}</ram:BilledQuantity></ram:SpecifiedLineTradeDelivery><ram:SpecifiedLineTradeSettlement><ram:ApplicableTradeTax><ram:TypeCode>VAT</ram:TypeCode><ram:CategoryCode>{l['cat']}</ram:CategoryCode><ram:RateApplicablePercent>{amt(l['rate'])}</ram:RateApplicablePercent></ram:ApplicableTradeTax>{allow}<ram:SpecifiedTradeSettlementLineMonetarySummation><ram:LineTotalAmount>{amt(l['line_net'])}</ram:LineTotalAmount></ram:SpecifiedTradeSettlementLineMonetarySummation></ram:SpecifiedLineTradeSettlement></ram:IncludedSupplyChainTradeLineItem>""")
    tax="".join(f"""<ram:ApplicableTradeTax><ram:CalculatedAmount>{amt(t['tax'])}</ram:CalculatedAmount><ram:TypeCode>VAT</ram:TypeCode>{'<ram:ExemptionReason>'+E(t['reason'])+'</ram:ExemptionReason>' if t.get('reason') else ''}<ram:BasisAmount>{amt(t['basis'])}</ram:BasisAmount><ram:CategoryCode>{t['cat']}</ram:CategoryCode><ram:RateApplicablePercent>{amt(t['rate'])}</ram:RateApplicablePercent></ram:ApplicableTradeTax>""" for t in inv['tax'])
    ac="".join(f"""<ram:SpecifiedTradeAllowanceCharge><ram:ChargeIndicator><udt:Indicator>{'true' if a['charge'] else 'false'}</udt:Indicator></ram:ChargeIndicator><ram:ActualAmount>{amt(a['amt'])}</ram:ActualAmount><ram:Reason>{E(a['reason'])}</ram:Reason><ram:CategoryTradeTax><ram:TypeCode>VAT</ram:TypeCode><ram:CategoryCode>{a['cat']}</ram:CategoryCode><ram:RateApplicablePercent>{amt(a['rate'])}</ram:RateApplicablePercent></ram:CategoryTradeTax></ram:SpecifiedTradeAllowanceCharge>""" for a in inv.get('doc_ac',[]))
    T=inv['tot']
    opt=lambda tag,k:f"<ram:{tag}>{amt(T[k])}</ram:{tag}>" if T.get(k) is not None else ""
    buyer_vat=f'<ram:SpecifiedTaxRegistration><ram:ID schemeID="VA">{inv["buyer_vat"]}</ram:ID></ram:SpecifiedTaxRegistration>' if inv.get('buyer_vat') else ""
    return f"""<?xml version="1.0" encoding="UTF-8"?>
<rsm:CrossIndustryInvoice xmlns:rsm="urn:un:unece:uncefact:data:standard:CrossIndustryInvoice:100" xmlns:ram="urn:un:unece:uncefact:data:standard:ReusableAggregateBusinessInformationEntity:100" xmlns:qdt="urn:un:unece:uncefact:data:standard:QualifiedDataType:100" xmlns:udt="urn:un:unece:uncefact:data:standard:UnqualifiedDataType:100"><rsm:ExchangedDocumentContext><ram:BusinessProcessSpecifiedDocumentContextParameter><ram:ID>urn:fdc:peppol.eu:2017:poacc:billing:01:1.0</ram:ID></ram:BusinessProcessSpecifiedDocumentContextParameter><ram:GuidelineSpecifiedDocumentContextParameter><ram:ID>urn:cen.eu:en16931:2017#compliant#urn:xeinkauf.de:kosit:xrechnung_3.0</ram:ID></ram:GuidelineSpecifiedDocumentContextParameter></rsm:ExchangedDocumentContext><rsm:ExchangedDocument><ram:ID>{inv['id']}</ram:ID><ram:TypeCode>{inv.get('type',380)}</ram:TypeCode><ram:IssueDateTime><udt:DateTimeString format="102">20261018</udt:DateTimeString></ram:IssueDateTime></rsm:ExchangedDocument><rsm:SupplyChainTradeTransaction>{''.join(L)}<ram:ApplicableHeaderTradeAgreement><ram:BuyerReference>04011000-12345-03</ram:BuyerReference><ram:SellerTradeParty><ram:Name>Muster Shop GmbH</ram:Name><ram:DefinedTradeContact><ram:PersonName>Max Muster</ram:PersonName><ram:TelephoneUniversalCommunication><ram:CompleteNumber>+49 1234 5678</ram:CompleteNumber></ram:TelephoneUniversalCommunication><ram:EmailURIUniversalCommunication><ram:URIID>shop@example.de</ram:URIID></ram:EmailURIUniversalCommunication></ram:DefinedTradeContact><ram:PostalTradeAddress><ram:PostcodeCode>10115</ram:PostcodeCode><ram:LineOne>Musterstr. 1</ram:LineOne><ram:CityName>Berlin</ram:CityName><ram:CountryID>DE</ram:CountryID></ram:PostalTradeAddress><ram:URIUniversalCommunication><ram:URIID schemeID="EM">shop@example.de</ram:URIID></ram:URIUniversalCommunication><ram:SpecifiedTaxRegistration><ram:ID schemeID="VA">DE123456789</ram:ID></ram:SpecifiedTaxRegistration></ram:SellerTradeParty><ram:BuyerTradeParty><ram:Name>Kunde AG</ram:Name><ram:PostalTradeAddress><ram:PostcodeCode>{inv.get('buyer_zip','80331')}</ram:PostcodeCode><ram:LineOne>Kundenweg 2</ram:LineOne><ram:CityName>{inv.get('buyer_city','München')}</ram:CityName><ram:CountryID>{inv.get('buyer_country','DE')}</ram:CountryID></ram:PostalTradeAddress><ram:URIUniversalCommunication><ram:URIID schemeID="EM">buyer@example.de</ram:URIID></ram:URIUniversalCommunication>{buyer_vat}</ram:BuyerTradeParty></ram:ApplicableHeaderTradeAgreement><ram:ApplicableHeaderTradeDelivery><ram:ActualDeliverySupplyChainEvent><ram:OccurrenceDateTime><udt:DateTimeString format="102">20261017</udt:DateTimeString></ram:OccurrenceDateTime></ram:ActualDeliverySupplyChainEvent></ram:ApplicableHeaderTradeDelivery><ram:ApplicableHeaderTradeSettlement><ram:InvoiceCurrencyCode>EUR</ram:InvoiceCurrencyCode><ram:SpecifiedTradeSettlementPaymentMeans><ram:TypeCode>58</ram:TypeCode><ram:PayeePartyCreditorFinancialAccount><ram:IBANID>DE79000000001234567890</ram:IBANID></ram:PayeePartyCreditorFinancialAccount></ram:SpecifiedTradeSettlementPaymentMeans>{tax}{ac}<ram:SpecifiedTradePaymentTerms><ram:Description>Zahlbar sofort.</ram:Description></ram:SpecifiedTradePaymentTerms><ram:SpecifiedTradeSettlementHeaderMonetarySummation><ram:LineTotalAmount>{amt(T['line'])}</ram:LineTotalAmount>{opt('ChargeTotalAmount','charge')}{opt('AllowanceTotalAmount','allow')}<ram:TaxBasisTotalAmount>{amt(T['basis'])}</ram:TaxBasisTotalAmount><ram:TaxTotalAmount currencyID="EUR">{amt(T['tax'])}</ram:TaxTotalAmount>{opt('RoundingAmount','rounding')}<ram:GrandTotalAmount>{amt(T['grand'])}</ram:GrandTotalAmount>{opt('TotalPrepaidAmount','prepaid')}<ram:DuePayableAmount>{amt(T['due'])}</ram:DuePayableAmount></ram:SpecifiedTradeSettlementHeaderMonetarySummation></ram:ApplicableHeaderTradeSettlement></rsm:SupplyChainTradeTransaction></rsm:CrossIndustryInvoice>"""
